function validate(input) {
  const [{ Signups = [], Confirmations = [] }] = input;
  const stamp = /^\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}$/;
  const users = new Set(), requests = new Set();
  for (const [user, time] of Signups) {
    if (user === null) return 'Every signup needs a user_id.';
    if (users.has(user)) return `user_id ${user} signs up twice.`;
    if (!stamp.test(String(time))) return `User ${user} has a malformed signup time.`;
    users.add(user);
  }
  for (const [user, time, action] of Confirmations) {
    if (!users.has(user)) return `Confirmation for user ${user}, who never signed up.`;
    if (!stamp.test(String(time))) return `User ${user} has a malformed confirmation time.`;
    if (action !== 'confirmed' && action !== 'timeout') return `Unknown action ${action}.`;
    const key = `${user}|${time}`;
    if (requests.has(key)) return `User ${user} has two confirmations at ${time}.`;
    requests.add(key);
  }
  return null;
}

