function generate(rand, size) {
  const small = size === 'small';
  const pick = list => list[Math.floor(rand() * list.length)];
  const text = seconds => new Date(seconds * 1000).toISOString().slice(0, 19).replace('T', ' ');
  // Gaps between consecutive requests sit on and around the 24-hour boundary.
  const gaps = [86400, 86401, 86399, 419, 3600, 88200, 90000, 172800, 50000, 1];
  const start = Date.UTC(2020, 11, 20) / 1000;
  const userCount = small ? Math.floor(rand() * 6) : 600;
  const cap = small ? 8 : 2000;
  const ids = [];
  for (let id = 1; id <= (small ? 9 : 900); id++) ids.push(id);
  for (let i = ids.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [ids[i], ids[j]] = [ids[j], ids[i]]; }
  const Signups = [], Confirmations = [];
  for (const user of ids.slice(0, userCount)) {
    let time = start + Math.floor(rand() * 40) * 86400 + Math.floor(rand() * 86400);
    Signups.push([user, text(time - 86400 * (1 + Math.floor(rand() * 30)) - Math.floor(rand() * 86400))]);
    const messages = Math.floor(rand() * (small ? 3 : 5));
    for (let m = 0; m < messages && Confirmations.length < cap; m++) {
      Confirmations.push([user, text(time), rand() < 0.5 ? 'confirmed' : 'timeout']);
      time += pick(gaps);
    }
  }
  // Shuffle so the rows of one user are not adjacent or sorted.
  for (let i = Confirmations.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [Confirmations[i], Confirmations[j]] = [Confirmations[j], Confirmations[i]]; }
  return [{ Signups, Confirmations }];
}
